begin;
create extension if not exists pgtap with schema extensions;
select no_plan();
create schema tests;
grant usage on schema tests to anon,authenticated;
create table tests.ids(label text primary key,id uuid);
grant all on tests.ids to authenticated;
create function tests.uid(p_name text) returns uuid language sql stable security definer as $$select id from auth.users where email=p_name||'@pr6.test'$$;
create function tests.act(p_name text) returns void language plpgsql as $$
begin
  reset role;
  if p_name='guest' then perform set_config('request.jwt.claims','{"role":"anon"}',true);perform set_config('role','anon',true);
  else perform set_config('request.jwt.claims',json_build_object('sub',tests.uid(p_name),'role','authenticated')::text,true);perform set_config('role','authenticated',true);end if;
end; $$;
insert into auth.users(id,email) select gen_random_uuid(),name||'@pr6.test' from unnest(array['admin','alice','bob','delete']) name;
update public.profiles set role='admin' where id=tests.uid('admin');
insert into tests.ids values('installation','aaaaaaaa-1111-4111-8111-111111111111'),('campaign',gen_random_uuid());
select tests.act('alice');
select public.register_push_token((select id from tests.ids where label='installation'),'ExpoPushToken[abcdefghijklmno]');
select public.register_push_token((select id from tests.ids where label='installation'),'ExpoPushToken[abcdefghijklmno]');
select is((select count(*) from public.push_tokens),1::bigint,'push registration is idempotent');
select throws_ok($$select public.register_push_token(gen_random_uuid(),'invalid')$$,'23514',null,'invalid push tokens rejected');
select throws_ok($$select public.send_notice(gen_random_uuid(),array[auth.uid()],'Title','Body')$$,'42501','admin_required','ordinary users cannot send notifications');
select tests.act('admin');
select is(public.send_notice((select id from tests.ids where label='campaign'),array[tests.uid('alice')],'Private title','Private body'),1,'admin creates inbox notice');
select is(public.send_notice((select id from tests.ids where label='campaign'),array[tests.uid('alice')],'Duplicate','Duplicate'),0,'campaign retry cannot duplicate notice');
select throws_ok($$select public.send_notice(gen_random_uuid(),array[]::uuid[],'Title','Body')$$,'P0001','invalid_recipients','empty campaigns rejected');
select tests.act('alice');
select is((select count(*) from public.notices),1::bigint,'recipient can read own inbox');
insert into tests.ids select 'notice',id from public.notices;
select public.mark_notice_read((select id from tests.ids where label='notice'));
select ok((select read_at is not null from public.notices),'recipient marks notice read');
select throws_ok($$update public.notices set body='forged'$$,'42501',null,'inbox contents are server-controlled');
select tests.act('bob');
select is((select count(*) from public.notices),0::bigint,'other users cannot read inbox contents');
select public.mark_notice_read((select id from tests.ids where label='notice'));
reset role;
create temp table claimed as select * from public.claim_push_deliveries(20);
select is((select count(*) from claimed),1::bigint,'one delivery exists per device and notice');
select is((select count(*) from public.claim_push_deliveries(20)),0::bigint,'leased push is not claimed twice');
select public.finish_push_delivery((select id from claimed),gen_random_uuid(),'delivered');
select is((select state from public.push_deliveries),'queued','stale worker cannot complete a delivery');
select public.finish_push_delivery((select id from claimed),(select lease_id from claimed),'waiting','expo-ticket');
select is((select state from public.push_deliveries),'waiting','Expo ticket waits for a receipt');
select ok((select next_attempt_at>=now()+interval '15 minutes' from public.push_deliveries),'receipt polling waits fifteen minutes');
update public.push_deliveries set next_attempt_at=now();
create temp table receipts as select * from public.claim_push_deliveries(20);
select public.finish_push_delivery((select id from receipts),(select lease_id from receipts),'failed',null,'DeviceNotRegistered',true);
select is((select enabled from public.push_tokens),false,'invalid receipt disables the device token');

select tests.act('alice');
select public.register_push_token((select id from tests.ids where label='installation'),'ExpoPushToken[abcdefghijklmno]');
select is((select enabled from public.push_tokens),true,'explicit registration re-enables a token');
select tests.act('bob');
select public.register_push_token(gen_random_uuid(),'ExpoPushToken[abcdefghijklmno]');
reset role;
select is((select count(*) from public.push_deliveries),0::bigint,'device account switch erases previous-account deliveries');
select is((select user_id from public.push_tokens),tests.uid('bob'),'device token moves to the authenticated account');
select public.finish_push_delivery((select id from receipts),(select lease_id from receipts),'failed',null,'DeviceNotRegistered',true);
select is((select enabled from public.push_tokens),true,'stale receipt cannot disable the moved registration');

-- Deletion fixtures: one publisher video, a personal object and attribution/payment data.
update public.profiles set can_publish=true where id=tests.uid('delete');
insert into public.channels(name,status,created_by) values('Delete channel','published',tests.uid('delete')) returning id;
insert into tests.ids select 'channel',id from public.channels where name='Delete channel';
insert into public.titles(channel_id,owner_id,kind,name,min_age,status)
 select id,tests.uid('delete'),'movie','Delete movie',0,'published' from tests.ids where label='channel';
insert into public.stream_assets(title_id,stream_uid,state,duration_seconds)
 select id,'44444444444444444444444444444444','ready',120 from public.titles where owner_id=tests.uid('delete');
insert into storage.objects(bucket_id,name,owner_id,metadata) values
 ('user-files',tests.uid('delete')||'/file',tests.uid('delete')::text,'{"size":10}'),
 ('user-files',tests.uid('bob')||'/file',tests.uid('bob')::text,'{"size":10}');
insert into public.app_installs(user_id,platform,tracking_consent,install_referrer) values(tests.uid('delete'),'android',true,'private-referrer');
insert into public.subscriptions(user_id,product_id,purchase_token,status,paid_until) values(tests.uid('delete'),'premium','pr6-erased-token','active',now()+interval '1 month');
insert into public.payment_events(provider_event_id,purchase_token,payload) values('pr6-before','pr6-erased-token','{"private":"data"}');
insert into public.meta_event_outbox(event_id,event_name,user_id) values('pr6-delete','Subscribe',tests.uid('delete'));
insert into auth.sessions(id,user_id,created_at,updated_at) values(gen_random_uuid(),tests.uid('delete'),now(),now());
insert into tests.ids select 'session',id from auth.sessions where user_id=tests.uid('delete');
select throws_ok($$select public.request_account_deletion(tests.uid('delete'),gen_random_uuid())$$,'42501','recent_sign_in_required','deletion requires a recent verified session');
update auth.sessions set created_at=now()-interval '16 minutes' where user_id=tests.uid('delete');
select throws_ok($$select public.request_account_deletion(tests.uid('delete'),(select id from tests.ids where label='session'))$$,'42501','recent_sign_in_required','an old session cannot request erasure');
update auth.sessions set created_at=now() where user_id=tests.uid('delete');
insert into tests.ids values('request',public.request_account_deletion(tests.uid('delete'),(select id from tests.ids where label='session')));
select is(public.request_account_deletion(tests.uid('delete'),(select id from tests.ids where label='session')),
 (select id from tests.ids where label='request'),'deletion requests are idempotent');
select is((select account_status from public.profiles where id=tests.uid('delete')),'suspended','deletion immediately restricts the account');
select is((select status from public.channels where id=(select id from tests.ids where label='channel')),'archived','deletion hides published owner content immediately');
select throws_ok($$update public.profiles set account_status='active' where id=tests.uid('delete')$$,'P0001','deletion_pending','admin cannot restore an account during erasure');
create temp table deletion as select * from public.claim_account_deletions(5);
select is((select count(*) from public.claim_account_deletions(5)),0::bigint,'erasure workers do not overlap');
select throws_ok($$select public.prepare_account_erasure(tests.uid('delete'),(select id from deletion),gen_random_uuid())$$,'P0001','deletion_lease_lost','unleased erasure is rejected');
select public.prepare_account_erasure(tests.uid('delete'),(select id from deletion),(select lease_id from deletion));
select is((select count(*) from public.titles where owner_id=tests.uid('delete')),0::bigint,'owned catalogue metadata is removed');
select is((select owner_id from public.stream_deletion_queue where stream_uid='44444444444444444444444444444444'),tests.uid('delete'),'external cleanup retains owner identity across metadata cascades');
select is((select count(*) from public.account_erasure_objects(tests.uid('delete'),(select id from deletion),(select lease_id from deletion))),1::bigint,'storage erasure selects only the target account objects');
select is((select count(*) from public.app_installs where user_id=tests.uid('delete')),0::bigint,'attribution is erased rather than anonymized with raw identifiers');
select is((select count(*) from public.meta_event_outbox where user_id=tests.uid('delete')),0::bigint,'pending conversions are erased');
select is((select count(*) from public.payment_events where purchase_token='pr6-erased-token'),0::bigint,'raw payment events are erased');
select ok(public.is_erased_purchase_token('pr6-erased-token'),'opaque tombstone recognizes late provider tokens');
insert into public.payment_events(provider_event_id,purchase_token,payload) values('pr6-after','pr6-erased-token','{"purchaseToken":"pr6-erased-token"}');
select is((select payload from public.payment_events where provider_event_id='pr6-after'),'{"erased":true}'::jsonb,'late notifications cannot recreate raw erased payloads');
select throws_ok($$update public.subscriptions set status='active' where purchase_token='pr6-erased-token'$$,'42501','purchase_erased','late verification cannot recreate an erased purchase');
select lives_ok($$select public.prepare_account_erasure(tests.uid('delete'),(select id from deletion),(select lease_id from deletion))$$,'erasure preparation is safely retryable');
create temp table media as select * from public.claim_media_deletions(20);
select public.finish_media_deletion('44444444444444444444444444444444',gen_random_uuid());
select is((select count(*) from public.stream_deletion_queue),1::bigint,'stale worker cannot finish external deletion');
select public.finish_media_deletion('44444444444444444444444444444444',(select lease_id from media));
select is((select count(*) from public.stream_deletion_queue),0::bigint,'successful provider deletion drains the durable queue');
delete from auth.users where id=tests.uid('delete');
select public.finish_account_deletion((select id from deletion),(select lease_id from deletion),true);
select is((select state from public.account_deletion_requests where id=(select id from deletion)),'complete','successful erasure completes the request');
select is((select user_id from public.account_deletion_requests where id=(select id from deletion)),null::uuid,'completed request drops its user identifier');
select ok(public.backend_health() ? 'missing_workers','health reports missing worker heartbeats');
select tests.act('alice');
select throws_ok($$select * from public.claim_account_deletions()$$,'42501',null,'users cannot operate deletion workers');
select throws_ok($$select public.backend_health()$$,'42501',null,'health aggregates are private');
select throws_ok($$select public.request_account_deletion(auth.uid(),gen_random_uuid())$$,'42501',null,'users cannot bypass authenticated deletion endpoint');
reset role;
select * from finish();
rollback;
